INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Embedded Systems dasselbe wie herkömmliche Computer?', 2, '[{"text": "Nein", "correct": true, "because": "Spezialisierte Funktion"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Embedded Systems?', 3, '[{"text": "Spezifische Aufgaben effizient lösen", "correct": true, "because": "Dedizierte Funktion"}, {"text": "Allgemeine Datenverarbeitung", "correct": false, "because": "PCs"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Embedded Systems?', 5, '[{"text": "Echtzeitfähigkeit", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Geringer Ressourcenbedarf", "correct": true, "because": "Effizienz"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Oft begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Embedded Systems sind in Geräte integriert. b) Sie sind immer vernetzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vernetzung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Embedded Systems?', 4, '[{"text": "Echtzeitverhalten", "correct": false, "because": "Oft entscheidend"}, {"text": "Ressourcenbeschränkung", "correct": false, "because": "Designfaktor"}, {"text": "Papierdokumente", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Embedded Systems immer Mikrocontroller nutzen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere CPUs"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware ist typisch für Embedded Systems?', 3, '[{"text": "Mikrocontroller", "correct": true, "because": "Kompakt und effizient"}, {"text": "High-End-GPU", "correct": false, "because": "Zu leistungsstark"}, {"text": "Papierdrucker", "correct": false, "because": "Keine Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Embedded Systems?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Optimiert für Aufgabe"}, {"text": "Kompakte Größe", "correct": true, "because": "Eingebettet"}, {"text": "Hohe Speicherleistung", "correct": false, "because": "Oft begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Embedded Systems sind spezialisiert. b) Sie haben immer eine Benutzeroberfläche. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UI optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Embedded Systems?', 4, '[{"text": "Mikroprozessor", "correct": false, "because": "Verarbeitung nötig"}, {"text": "Firmware", "correct": false, "because": "Softwarebasis"}, {"text": "Großer Bildschirm", "correct": true, "because": "Oft ohne UI"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Embedded Systems immer vernetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Standalone möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Embedded Systems?', 4, '[{"text": "Automobiltechnik", "correct": true, "because": "Steuergeräte"}, {"text": "Haushaltsgeräte", "correct": true, "because": "Z. B. Mikrowellen"}, {"text": "Papierverarbeitung", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Embedded Systems nur für große Geräte sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Geräte"}, {"text": "Ja", "correct": false, "because": "Kompakt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Embedded Systems?', 3, '[{"text": "Effizienz", "correct": true, "because": "Ressourcen sparen"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}, {"text": "Maximale Leistung", "correct": false, "because": "Spezifisch optimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Embedded Systems haben feste Aufgaben. b) Sie sind immer leistungsstark.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen nutzen Embedded Systems?', 5, '[{"text": "C", "correct": true, "because": "Effizient und nah an Hardware"}, {"text": "C++", "correct": true, "because": "Objektorientiert"}, {"text": "HTML", "correct": false, "because": "Webentwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Embedded Systems unwichtig?', 3, '[{"text": "Echtzeitfähigkeit", "correct": false, "because": "Oft entscheidend"}, {"text": "Ressourcenbedarf", "correct": false, "because": "Effizienz"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Benötigen Embedded Systems immer eine Stromversorgung?', 3, '[{"text": "Ja", "correct": true, "because": "Elektronik"}, {"text": "Nein", "correct": false, "because": "Strom nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Embedded Systems für Gaming geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Spezialisierte Aufgaben"}, {"text": "Ja", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Embedded Systems zentral?', 4, '[{"text": "Spezifische Funktion", "correct": true, "because": "Dediziertes Design"}, {"text": "Maximale Speicherkapazität", "correct": false, "because": "Oft begrenzt"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}]');
